input.command:
read_cpu() { awk '{print $14+$15+$16+$17}' /proc/$1/stat 2>/dev/null; }
state() { awk '{print $3}' /proc/$1/stat 2>/dev/null; }
thr() { cat /proc/$1/status 2>/dev/null | awk '/Threads/{print $2}'; }
echo "OLD 1189747: cpu0=$(read_cpu 1189747) state=$(state 1189747) threads=$(thr 1189747)"
echo "NEW 1205998: cpu0=$(read_cpu 1205998) state=$(state 1205998) threads=$(thr 1205998)"
sleep 6
echo "--- after 6s ---"
echo "OLD 1189747: cpu1=$(read_cpu 1189747) state=$(state 1189747)"
echo "NEW 1205998: cpu1=$(read_cpu 1205998) state=$(state 1205998)"
echo "(cpu units = clock ticks, $(getconf CLK_TCK)/s)"
